/**
 * ObtÃ©m o CSV como texto vindo de um HTTP Request
 */
const csvRaw = $json.data ?? $json.body ?? $json;

const text = typeof csvRaw === "string"
  ? csvRaw
  : JSON.stringify(csvRaw);

// Divide o texto em linhas e remove linhas vazias
const lines = text
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(Boolean);

// Evita processar um CSV vazio
if (lines.length === 0) {
  return [{ json: { investimentos: [] } }];
}

// Extrai os cabeÃ§alhos
const headers = lines[0]
  .split(",")
  .map(h => h.trim());

// Converte as linhas em objetos
const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Normaliza "minimo" para nÃºmero
  obj.minimo = Number(
    String(obj.minimo ?? "").replace(/[^\d]/g, "")
  ) || 0;

  return obj;
});

// Retorna os dados no formato esperado pelo n8n
return [
  {
    json: {
      investimentos
    }
  }
];

// ObtÃ©m a entrada unificada vinda do nÃ³ Merge
const entrada = $input.first().json;

// Extrai clientes (suporta variaÃ§Ãµes do payload do webhook) e investimentos
const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

// Converte valores monetÃ¡rios como "R$ 12.500,00" para nÃºmero (ex: 12500)
function converterParaNumero(valor) {
  if (typeof valor === "number") return valor;

  const numero = String(valor ?? "")
    .replace(/[^\d,.-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  return Number(numero) || 0;
}

// Formata valores numÃ©ricos para o padrÃ£o de moeda brasileiro (R$)
function formatarMoeda(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

// Normaliza textos (remove espaÃ§os e converte para minÃºsculas)
function normalizarTexto(valor) {
  return String(valor ?? "").trim().toLowerCase();
}

// Processa e cruza cada cliente com a lista de investimentos
const resultados = clientes.map((cliente) => {
  const saldoNum = converterParaNumero(cliente.saldo);
  const perfilCliente = normalizarTexto(cliente.perfil);

  // Filtra opÃ§Ãµes compatÃ­veis com o perfil e cujo valor mÃ­nimo seja <= ao saldo do cliente
  const compativeis = investimentos.filter((investimento) => {
    const perfilInvestimento = normalizarTexto(investimento.perfil);
    const minimo = converterParaNumero(investimento.minimo);

    const perfilCompativel =
      !perfilInvestimento || perfilInvestimento === perfilCliente;

    return perfilCompativel && saldoNum >= minimo;
  });

  // Seleciona a primeira opÃ§Ã£o compatÃ­vel
  const escolhido = compativeis[0] ?? null;

  // Templates de mensagens estÃ¡ticas (Etapa 4 - MVP)
  const mensagens = escolhido
    ? [
        `OlÃ¡, ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opÃ§Ã£o Ã© o ${escolhido.produto} (mÃ­nimo ${formatarMoeda(converterParaNumero(escolhido.minimo))}). Com seu saldo atual de ${formatarMoeda(saldoNum)}, vocÃª jÃ¡ consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi, ${cliente.nome}! RecomendaÃ§Ã£o para perfil ${cliente.perfil}: ${escolhido.produto}. Seu saldo de ${formatarMoeda(saldoNum)} atende ao valor mÃ­nimo de ${formatarMoeda(converterParaNumero(escolhido.minimo))}. Rentabilidade: ${escolhido.rentabilidade}.`,
        `${cliente.nome}, considerando seu perfil ${cliente.perfil}, o ${escolhido.produto} pode ser uma opÃ§Ã£o. VocÃª tem ${formatarMoeda(saldoNum)} disponÃ­veis e o investimento exige no mÃ­nimo ${formatarMoeda(converterParaNumero(escolhido.minimo))}. Rentabilidade: ${escolhido.rentabilidade}.`,
      ]
    : [
        `OlÃ¡, ${cliente.nome}! No momento, nÃ£o encontramos um investimento compatÃ­vel com seu perfil e saldo atual de ${formatarMoeda(saldoNum)}.`,
      ];

  // Escolhe aleatoriamente uma variaÃ§Ã£o de template
  const mensagemEscolhida =
    mensagens[Math.floor(Math.random() * mensagens.length)];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: formatarMoeda(saldoNum),
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo: escolhido ? "saldo_ok" : "sem_opcao_compativel",
    mensagens,
    mensagem_escolhida: mensagemEscolhida,
  };
});

// Retorna o resultado final estruturado para o nÃ³ 'Respond to Webhook'
return [
  {
    json: {
      ok: true,
      total_clientes: resultados.length,
      total_investimentos: investimentos.length,
      resultados,
    },
  },
];
